import java.util.*;

public class Task7 {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        int B = input.nextInt();

        int[] array = new int[n];
        for (int i = 0; i < n; i++) {
            array[i] = input.nextInt();
        }

        int evenCount = 0, oddCount = 0;
        List<Integer> diffList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (array[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (evenCount == oddCount && i < n - 1) {
                diffList.add(Math.abs(array[i] - array[i + 1]));
            }
        }
        Collections.sort(diffList);
        int total = 0;
        for (int diff : diffList) {
            if (B < diff) {
                break;
            }
            total++;
            B -= diff;
        }
        System.out.println(total);
        input.close();
    }
}
