#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n, B;
    std::cin >> n >> B;

    std::vector<int> array(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> array[i];
    }

    int evenCount = 0, oddCount = 0;
    std::vector<int> diffList;
    for (int i = 0; i < n; ++i) {
        if (array[i] % 2 == 0) {
            ++evenCount;
        } else {
            ++oddCount;
        }
        if (evenCount == oddCount && i < n - 1) {
            diffList.push_back(std::abs(array[i] - array[i + 1]));
        }
    }

    std::sort(diffList.begin(), diffList.end());

    int total = 0;
    for (int diff : diffList) {
        if (B < diff) {
            break;
        }
        ++total;
        B -= diff;
    }

    std::cout << total << std::endl;
    return 0;
}
